using System.Linq;using UnityEngine;using UnityEditor;using CatGunner.Runtime;
public static class InspectUiLayering
{
 static string Path(Transform t){return t.parent==null?t.name:Path(t.parent)+"/"+t.name;}
 public static object Main(){var c=Object.FindAnyObjectByType<GameClient>(FindObjectsInactive.Include);var root=c.Slider.GetComponentInParent<Canvas>();
 var joysticks=root.GetComponentsInChildren<FloatingJoystick>(true);
 return Newtonsoft.Json.JsonConvert.SerializeObject(new{scene=c.gameObject.scene.path,dirty=c.gameObject.scene.isDirty,joysticks=joysticks.Select(j=>new{path=Path(j.transform),images=j.GetComponentsInChildren<UnityEngine.UI.Image>(true).Select(i=>new{path=Path(i.transform),sprite=i.sprite!=null?i.sprite.name:null,asset=AssetDatabase.GetAssetPath(i.sprite),size=new[]{i.rectTransform.sizeDelta.x,i.rectTransform.sizeDelta.y},rect=new[]{i.rectTransform.rect.width,i.rectTransform.rect.height},color=new[]{i.color.r,i.color.g,i.color.b,i.color.a},type=i.type.ToString()})}),loading=Path(c.LoadingUI.transform),mainChildren=c.LoadingUI.transform.parent.Cast<Transform>().Select(t=>new{t.name,index=t.GetSiblingIndex()}),canvases=root.GetComponentsInChildren<Canvas>(true).Select(v=>new{path=Path(v.transform),v.overrideSorting,v.sortingOrder,mode=v.renderMode.ToString(),active=v.gameObject.activeSelf,modal=v.GetComponent<PenguinModalLayer>()!=null}),borderCount=root.GetComponentsInChildren<PenguinPanelBorder>(true).Length,bordersLast=root.GetComponentsInChildren<PenguinPanelBorder>(true).Count(b=>b.transform.GetSiblingIndex()>0),cameras=Object.FindObjectsByType<Camera>(FindObjectsInactive.Include,FindObjectsSortMode.None).Select(cam=>new{cam.name,cam.depth,cam.orthographic}),circles=AssetDatabase.FindAssets("Circle t:Sprite").Take(30).Select(AssetDatabase.GUIDToAssetPath)});}
}
